insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  12,
  $wyb$A command-line tool that reads a folder of unstructured text files - a business card blurb, an email signature, a real-estate listing, a job posting - and calls your own AI key (Gemini or Claude) to pull out name, email, phone, date and amount fields. The AI answers using bracket markers instead of JSON, so a slightly-off reply degrades gracefully instead of crashing the whole batch, and it's explicitly told to write "none" for anything it can't find rather than guess. Every extracted record is compiled into a single output.csv with pandas, ready to open in Excel or Google Sheets.$wyb$,
  $wyl$[
  "Design a prompt with bracket markers instead of JSON, and explain why that's more forgiving for a beginner project",
  "Instruct an AI to admit when it can't find something, instead of guessing",
  "Parse an AI reply into a dict that survives a missing field and an unrecognised extra marker",
  "Convert a list of extracted records into a clean CSV with pandas",
  "Batch-process a folder of mixed real-world documents through one pipeline",
  "Write self-tests for parsing logic that don't require a live AI call or spend any credits",
  "Verify an AI tool's honesty with a concrete, checkable test rather than eyeballing the output"
]$wyl$::jsonb,
  $sess${
  "model": "Gemini 3.7 Flash or Claude Haiku 4.5 (your choice - see sdt_ai.py setup)",
  "totalTime": "90 min",
  "buildCount": 4,
  "whatYouNeed": [
    "A free Gemini API key (aistudio.google.com/apikey) OR your own Claude/Anthropic API key (console.anthropic.com/settings/keys)",
    "Python 3.10+ installed",
    "Basic pandas familiarity"
  ],
  "outcomes": [
    "Design a prompt that extracts specific fields from messy text using bracket markers instead of JSON",
    "Parse an AI reply into a clean dict that handles a missing field and an unexpected extra section without crashing",
    "Turn a list of extracted records into a clean CSV with pandas",
    "Batch-process a whole folder of mixed real-world documents through one pipeline",
    "Prove your extractor is honest: confirm it reports \"none\" instead of inventing a plausible-looking value"
  ],
  "builds": [
    {
      "number": 1,
      "title": "Connect to the AI and design your extraction prompt",
      "time": "30 min",
      "description": "Wire up the shared AI connector, then teach it exactly what to look for and how to answer - this is the one prompt the whole project runs on.",
      "steps": [
        {
          "instruction": "Create `sdt_ai.py` in your project folder with this code. You'll reuse this exact file, unmodified, in every future AI Builder project:",
          "prompt": "\"\"\"\nSocial Dev AI Builder - your connection to the AI.\n\nYou have TWO ways to power this file. Pick ONE and set it in your .env:\n\n  AI_PROVIDER=gemini    -> your own FREE Google Gemini API key\n  AI_PROVIDER=claude    -> your own Claude/Anthropic API key\n\nEvery project in this course calls ask_ai(...) the exact same way no\nmatter which one you pick - this file is the only place that changes.\n\nSETUP - OPTION 1: Gemini (free, no billing needed):\n\n  1. Go to https://aistudio.google.com/apikey and sign in with any Google\n     account. Click \"Create API key\" - free, no card required.\n  2. In the same folder as this file, create a file named exactly: .env\n  3. Put these two lines inside it:\n\n         AI_PROVIDER=gemini\n         GEMINI_API_KEY=paste_your_own_key_here\n\nSETUP - OPTION 2: Claude (if you already have a paid Claude account):\n\n  1. Go to https://console.anthropic.com/settings/keys and create an API\n     key. This needs billing set up on your Anthropic account - it is a\n     separate thing from a claude.ai Pro subscription, and is billed by\n     Anthropic based on what you actually use.\n  2. In your .env file, put these two lines instead:\n\n         AI_PROVIDER=claude\n         ANTHROPIC_API_KEY=paste_your_own_key_here\n\nNever share either key or put it on GitHub - each one is billed to YOUR\naccount. That's it. Every project in this course reuses this same file.\n\"\"\"\n\nimport os\nimport time\n\nimport requests\nfrom dotenv import load_dotenv\n\n# Reads the .env file sitting next to your project and loads your keys.\nload_dotenv()\n\n# gemini-3.7-flash first - the current stable/GA flash model. If it's\n# ever down (Google's free tier occasionally returns 503 \"high demand\"\n# on a single model for hours at a time), gemini-2.5-flash is a real\n# fallback, not a downgrade-and-forget: a different model is a\n# different capacity pool, so it's often still up during a\n# 3.7-specific outage. Set GEMINI_MODEL in .env to pin one specific\n# model instead and skip the fallback entirely.\n_env_model = os.environ.get(\"GEMINI_MODEL\")\nGEMINI_MODELS = [_env_model] if _env_model else [\"gemini-3.7-flash\", \"gemini-2.5-flash\"]\nGEMINI_URL_TEMPLATE = \"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent\"\n\nCLAUDE_MODEL = os.environ.get(\"CLAUDE_MODEL\", \"claude-haiku-4-5\")\nANTHROPIC_URL = \"https://api.anthropic.com/v1/messages\"\nANTHROPIC_VERSION = \"2023-06-01\"\n\n# Gemini's free tier occasionally answers 503 (\"model overloaded\") during\n# busy periods - that's not your code being wrong, retrying a couple of\n# times almost always gets a real answer.\nMAX_ATTEMPTS = 3\nRETRY_DELAY_SECONDS = 3\n\n\nclass AIError(Exception):\n    \"\"\"Something went wrong talking to the AI. The message explains what.\"\"\"\n\n\ndef _get_provider():\n    \"\"\"\n    Reads AI_PROVIDER from .env. Falls back to guessing from whichever key\n    is actually present, so forgetting to set AI_PROVIDER explicitly\n    doesn't crash a setup that only has one key configured.\n    \"\"\"\n    provider = os.environ.get(\"AI_PROVIDER\", \"\").strip().lower()\n    if provider in (\"gemini\", \"claude\"):\n        return provider\n\n    if os.environ.get(\"GEMINI_API_KEY\"):\n        return \"gemini\"\n    if os.environ.get(\"ANTHROPIC_API_KEY\"):\n        return \"claude\"\n\n    raise AIError(\n        \"No AI provider configured.\\n\"\n        \"Add ONE of these pairs to your .env file:\\n\\n\"\n        \"    AI_PROVIDER=gemini\\n\"\n        \"    GEMINI_API_KEY=paste_your_free_key_here\\n\\n\"\n        \"  ...or...\\n\\n\"\n        \"    AI_PROVIDER=claude\\n\"\n        \"    ANTHROPIC_API_KEY=paste_your_own_key_here\\n\\n\"\n        \"Get a free Gemini key at https://aistudio.google.com/apikey\"\n    )\n\n\ndef _ask_gemini_model(model, api_key, payload):\n    \"\"\"\n    Tries ONE Gemini model, retrying up to MAX_ATTEMPTS times on a 503\n    (\"high demand\") before giving up on this model. Returns the parsed\n    result dict, or raises AIError - including a distinct AIError for a\n    503 that never cleared, so _ask_gemini() below can tell \"this model\n    is down, try the next one\" apart from every other failure.\n    \"\"\"\n    url = GEMINI_URL_TEMPLATE.format(model=model)\n\n    for attempt in range(MAX_ATTEMPTS):\n        try:\n            response = requests.post(url, params={\"key\": api_key}, json=payload, timeout=90)\n        except requests.RequestException:\n            raise AIError(\n                \"Could not reach Gemini. Check your internet connection and try again.\"\n            )\n\n        if response.status_code == 503:\n            if attempt < MAX_ATTEMPTS - 1:\n                time.sleep(RETRY_DELAY_SECONDS)\n                continue\n            raise AIError(f\"{model} is busy (503 - high demand)\")\n\n        if response.status_code == 429:\n            raise AIError(\n                \"Gemini says you've hit the free tier's rate limit. Wait a \"\n                \"minute and try again.\"\n            )\n\n        if response.status_code == 400:\n            raise AIError(\n                f\"Gemini rejected the request - double check your GEMINI_API_KEY \"\n                f\"is correct: {response.text[:300]}\"\n            )\n\n        if response.status_code != 200:\n            raise AIError(\n                f\"Gemini returned an error (status {response.status_code}): {response.text[:300]}\"\n            )\n\n        data = response.json()\n        try:\n            candidate = data[\"candidates\"][0]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply from Gemini: {data}\")\n\n        if candidate.get(\"finishReason\") == \"SAFETY\":\n            raise AIError(\"Gemini declined to answer (safety filter). Try rephrasing your prompt.\")\n\n        try:\n            text = candidate[\"content\"][\"parts\"][0][\"text\"]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply shape from Gemini: {data}\")\n\n        usage = data.get(\"usageMetadata\", {})\n        return {\n            \"text\": text,\n            \"input_tokens\": usage.get(\"promptTokenCount\"),\n            \"output_tokens\": usage.get(\"candidatesTokenCount\"),\n        }\n\n\ndef _ask_gemini(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"GEMINI_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to gemini but no GEMINI_API_KEY was found.\\n\"\n            \"Get a free key at https://aistudio.google.com/apikey and add \"\n            \"it to .env:\\n\"\n            \"    GEMINI_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"contents\": [{\"role\": \"user\", \"parts\": [{\"text\": prompt}]}],\n        \"generationConfig\": {\"maxOutputTokens\": max_tokens},\n    }\n    if system:\n        payload[\"systemInstruction\"] = {\"parts\": [{\"text\": system}]}\n\n    # Try each model in GEMINI_MODELS in order - a 503 that survives every\n    # retry on one model falls through to the next, since a different\n    # model is a different capacity pool and is often still up during a\n    # model-specific outage. Any other kind of failure (bad key, rate\n    # limit, safety block) is raised immediately instead of wasted on a\n    # second model that would fail the exact same way.\n    last_problem = None\n    for model in GEMINI_MODELS:\n        try:\n            return _ask_gemini_model(model, api_key, payload)\n        except AIError as problem:\n            if \"high demand\" not in str(problem):\n                raise\n            last_problem = problem\n\n    raise AIError(\n        f\"Gemini was unavailable after trying {', '.join(GEMINI_MODELS)} ({last_problem}). \"\n        \"This happens sometimes on the free tier during high demand - wait \"\n        \"a minute and try again.\"\n    )\n\n\ndef _ask_claude(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"ANTHROPIC_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to claude but no ANTHROPIC_API_KEY was found.\\n\"\n            \"Create one at https://console.anthropic.com/settings/keys and \"\n            \"add it to .env:\\n\"\n            \"    ANTHROPIC_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"model\": CLAUDE_MODEL,\n        \"max_tokens\": max_tokens,\n        \"messages\": [{\"role\": \"user\", \"content\": prompt}],\n    }\n    if system:\n        payload[\"system\"] = system\n\n    try:\n        response = requests.post(\n            ANTHROPIC_URL,\n            headers={\n                \"x-api-key\": api_key,\n                \"anthropic-version\": ANTHROPIC_VERSION,\n                \"Content-Type\": \"application/json\",\n            },\n            json=payload,\n            timeout=90,\n        )\n    except requests.RequestException:\n        raise AIError(\"Could not reach Claude. Check your internet connection and try again.\")\n\n    try:\n        data = response.json()\n    except ValueError:\n        raise AIError(f\"Unexpected reply from Claude (status {response.status_code}).\")\n\n    if response.status_code == 401:\n        raise AIError(\n            \"Claude rejected your ANTHROPIC_API_KEY - double check it was copied correctly.\"\n        )\n\n    if response.status_code == 429:\n        raise AIError(\"Claude says you've hit your rate or usage limit. Wait a moment and try again.\")\n\n    if \"error\" in data:\n        raise AIError(data[\"error\"].get(\"message\", str(data[\"error\"])))\n\n    text = \"\".join(\n        block.get(\"text\", \"\") for block in data.get(\"content\", []) if block.get(\"type\") == \"text\"\n    )\n    usage = data.get(\"usage\", {})\n    return {\n        \"text\": text,\n        \"input_tokens\": usage.get(\"input_tokens\"),\n        \"output_tokens\": usage.get(\"output_tokens\"),\n    }\n\n\ndef ask_ai_detailed(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Same as ask_ai, but returns the whole reply as a dict.\n\n        result = ask_ai_detailed(\"Summarise this\", max_tokens=200)\n        print(result[\"text\"])\n    \"\"\"\n    provider = _get_provider()\n    if provider == \"gemini\":\n        return _ask_gemini(prompt, system=system, max_tokens=max_tokens)\n    return _ask_claude(prompt, system=system, max_tokens=max_tokens)\n\n\ndef ask_ai(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Send a question to the AI and get the answer back as text.\n\n        answer = ask_ai(\"Write a haiku about Lagos traffic\")\n        print(answer)\n\n    prompt      - what you want the AI to do. This is the important part.\n    system      - optional. Sets the AI's role, e.g. \"You are a careful editor.\"\n    max_tokens  - roughly how long the answer may be. 1000 is plenty for most.\n    project     - unused, kept so call sites read the same across every\n                  project regardless of which AI is behind this file.\n\n    Works identically whichever provider your .env is set to - every\n    project in this course calls this one function and never needs to\n    know which AI is actually answering.\n\n    Returns the AI's answer as a plain string.\n    Raises AIError with a readable message if something is wrong.\n    \"\"\"\n    return ask_ai_detailed(prompt, system=system, max_tokens=max_tokens, project=project)[\"text\"]\n\n\nif __name__ == \"__main__\":\n    # Running this file directly checks that your setup works.\n    print(\"Testing your AI Builder connection...\\n\")\n    try:\n        provider = _get_provider()\n        result = ask_ai_detailed(\"Say hello in exactly five words.\", max_tokens=50)\n        print(f\"Provider: {provider}\")\n        print(\"The AI said:\", result[\"text\"])\n        print(\"\\nYour setup works. You are ready to build.\")\n    except AIError as problem:\n        print(\"Setup problem:\\n\")\n        print(problem)\n",
          "verify": "Don't run it yet - it needs the .env file from the next step first."
        },
        {
          "instruction": "Create `.env` in the same folder with ONE of the two setups below — pick whichever you're using, then replace the placeholder with your real key:",
          "prompt": "# OPTION 1: your own free Gemini key (recommended - no billing needed)\n# Get one free at https://aistudio.google.com/apikey - no credit card needed\nAI_PROVIDER=gemini\nGEMINI_API_KEY=paste_your_own_key_here\n\n# OPTION 2: your own Claude/Anthropic key (comment OPTION 1 out above,\n# uncomment these two lines instead - needs billing set up on your own\n# Anthropic account)\n# Get one at https://console.anthropic.com/settings/keys\n# AI_PROVIDER=claude\n# ANTHROPIC_API_KEY=paste_your_own_key_here\n",
          "verify": "Run `python sdt_ai.py` - it should print which provider you're using, then `The AI said: ...`, and end with `Your setup works. You are ready to build.` If you see `No AI provider configured` instead, check that .env sits next to sdt_ai.py and that AI_PROVIDER plus its matching key are both uncommented."
        },
        {
          "instruction": "Create `extractor.py` with this code:",
          "prompt": "\"\"\"\nStep 1 of the Basic Data Extractor Agent.\n\nThis file has one job: given raw unstructured text (a business card\nblurb, an email signature, a listing - anything), ask the AI to pull out\na handful of specific fields, then turn its reply into a clean dict.\n\"\"\"\n\nfrom sdt_ai import ask_ai\n\n# The fields we ask the AI to find, and a precise one-line description of\n# what counts for each. The wording matters more than it looks - without\n# \"a person's name (not a company or product name)\", the AI will happily\n# hand back \"EcoBrew\" or \"TechNova Inc.\" for NAME, which technically fills\n# the marker but is the wrong extraction for a name column.\nFIELDS = {\n    \"NAME\": \"The full name of a specific person mentioned in the text (not a company or product name).\",\n    \"EMAIL\": \"An email address mentioned in the text.\",\n    \"PHONE\": \"A phone number mentioned in the text, in whatever format it appears.\",\n    \"DATE\": \"A specific date mentioned in the text (a deadline, listing date, event date, etc.).\",\n    \"AMOUNT\": \"A specific monetary amount mentioned in the text (a price, salary, fee), including its currency symbol or code.\",\n}\n\n\ndef build_prompt(text):\n    \"\"\"\n    Writes the instructions we send to the AI.\n\n    Keeping this in its own function means you can print it and read\n    exactly what the AI was asked, which is the fastest way to fix a\n    field that keeps coming back wrong.\n    \"\"\"\n    field_list = \"\\n\".join(f\"[{name}] {description}\" for name, description in FIELDS.items())\n\n    return f\"\"\"Extract the following fields from the text below.\n\nFields to find:\n{field_list}\n\nFormat your answer EXACTLY like this, one marker per line followed by\nthe value on the next line:\n\n[NAME]\nvalue or none\n\n[EMAIL]\nvalue or none\n\n...and so on for PHONE, DATE and AMOUNT.\n\nAfter the last field, write [END] on its own line.\n\nIMPORTANT: if a field is not clearly present in the text, write exactly\nthe word \"none\" under that marker. Do NOT guess, estimate, or invent a\nplausible-looking value - a confidently wrong answer is worse than an\nhonest \"none\", because whoever reads the CSV later has no way to tell\nthe difference between a real value and a guess.\n\nDo not add any explanation, introduction or closing remark.\n\nTEXT:\n{text}\"\"\"\n\n\ndef parse_fields(reply):\n    \"\"\"\n    Turns the AI's reply into a dict, one entry per field:\n\n        {\"NAME\": \"Sarah Okafor\", \"EMAIL\": \"...\", \"PHONE\": None, ...}\n\n    Same [MARKER] approach as the Social Post Generator's split_posts()\n    (see generator.py in that project) - we ask for bracket markers\n    rather than JSON on purpose. JSON breaks the whole parse on a single\n    stray comma or a markdown code fence around the reply; markers\n    degrade gracefully, one field at a time.\n\n    A field the AI marked \"none\" comes back as a real Python None, not\n    the string \"none\" - that way pandas writes a genuinely blank cell\n    later instead of every empty column literally saying \"none\".\n\n    Any marker we don't recognise (and everything under it, until the\n    next marker we DO recognise) is dropped rather than glued onto\n    whichever field happened to be active - otherwise an AI that adds an\n    unrequested [NOTES] section would silently corrupt the field before it.\n    \"\"\"\n    values = {}\n    current_field = None\n    current_lines = []\n\n    def save_current():\n        if current_field:\n            value = \"\\n\".join(current_lines).strip()\n            values[current_field] = None if value.lower() == \"none\" else value\n\n    for line in reply.splitlines():\n        stripped = line.strip()\n        marker = stripped.strip(\"[]\").upper()\n        is_marker = stripped.startswith(\"[\") and stripped.endswith(\"]\") and len(stripped) > 2\n\n        if is_marker and marker == \"END\":\n            break\n\n        if is_marker and marker in FIELDS:\n            save_current()\n            current_field = marker\n            current_lines = []\n        elif is_marker:\n            # An unrecognised marker. Save whatever field we were\n            # building, then stop collecting until the next marker we\n            # DO recognise - see the docstring above for why.\n            save_current()\n            current_field = None\n            current_lines = []\n        elif current_field:\n            # The AI sometimes wraps its whole answer in ``` code fences.\n            # Those aren't part of a value, so drop them.\n            if stripped.startswith(\"```\"):\n                continue\n            current_lines.append(line)\n\n    save_current()\n\n    # Every field always ends up as a key, even one the AI's reply never\n    # produced a marker for at all (rare, but the reply shape isn't\n    # guaranteed) - so main.py and csv_writer.py can rely on every\n    # record having the same keys.\n    for name in FIELDS:\n        values.setdefault(name, None)\n\n    return values\n\n\ndef extract_fields(text, source_file=None):\n    \"\"\"\n    The main function. Give it raw text, get back a dict of fields.\n\n        data = extract_fields(open(\"sample_data/business_card.txt\").read())\n        print(data[\"EMAIL\"])\n    \"\"\"\n    prompt = build_prompt(text)\n\n    # max_tokens caps how long the AI's answer may be, which caps what\n    # this costs you. Five short field values (a name, an email, a\n    # phone number...) comfortably fit in 200 tokens - there's no\n    # paragraph-length output here, just a handful of short values.\n    reply = ask_ai(\n        prompt,\n        max_tokens=200,\n        project=\"basic-data-extractor-agent\",\n    )\n\n    data = parse_fields(reply)\n    if source_file:\n        data[\"source_file\"] = source_file\n\n    return data\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing works - no AI call,\n    # no credits spent, just proving parse_fields() handles real and\n    # awkward replies correctly:  python extractor.py\n    print(\"--- Testing a normal reply ---\")\n    normal_reply = \"\"\"[NAME]\nSarah Okafor\n\n[EMAIL]\nsarah.okafor@fintechsolutions.ng\n\n[PHONE]\n+234 803 555 0192\n\n[DATE]\nnone\n\n[AMOUNT]\nnone\n\n[END]\"\"\"\n    result = parse_fields(normal_reply)\n    for field, value in result.items():\n        print(f\"{field}: {value!r}\")\n    assert result[\"NAME\"] == \"Sarah Okafor\"\n    assert result[\"DATE\"] is None\n\n    print(\"\\n--- Testing a reply with a missing field (must be None, not a crash) ---\")\n    missing_reply = \"\"\"[NAME]\nDavid Chen\n\n[EMAIL]\ndavid.chen@brightpathconsulting.com\n\n[PHONE]\nnone\n\n[DATE]\nnone\n\n[AMOUNT]\nnone\n\n[END]\"\"\"\n    result = parse_fields(missing_reply)\n    assert result[\"PHONE\"] is None, \"A field marked 'none' by the AI must parse to None, not the string 'none'\"\n    print(\"PHONE correctly parsed as:\", result[\"PHONE\"])\n    print(\"Full result:\", result)\n\n    print(\"\\n--- Testing a reply with extra, unrecognised markers (must be ignored, not crash) ---\")\n    extra_marker_reply = \"\"\"[NAME]\nChidinma Eze\n\n[EMAIL]\nnone\n\n[PHONE]\n0807 123 4567\n\n[DATE]\n2026-08-15\n\n[AMOUNT]\nNGN 85,000,000\n\n[CONFIDENCE]\nhigh\n\n[NOTES]\nThis is a real estate listing, not a business card.\n\n[END]\"\"\"\n    result = parse_fields(extra_marker_reply)\n    assert \"CONFIDENCE\" not in result, \"Unrecognised markers must be ignored, not added to the result\"\n    assert \"NOTES\" not in result, \"Unrecognised markers must be ignored, not added to the result\"\n    assert result[\"AMOUNT\"] == \"NGN 85,000,000\", \"The real AMOUNT value must survive an unrecognised marker right after it\"\n    assert result[\"EMAIL\"] is None\n    print(\"Unrecognised markers correctly ignored. Full result:\", result)\n\n    print(\"\\nAll parser self-tests passed.\")\n",
          "verify": "Run `python extractor.py` - it parses three synthetic AI replies with no network call at all (a normal reply, one with a field missing, and one with extra markers the AI wasn't asked for), and ends with `All parser self-tests passed.` and no error. This test costs zero credits - it checks your parsing logic, not the AI."
        }
      ],
      "goFurther": "Change the FIELDS dict to extract fields relevant to a document type you care about instead (e.g. INVOICE_NUMBER, VENDOR, DUE_DATE) and see how little else in the file has to change."
    },
    {
      "number": 2,
      "title": "Write extracted records to a clean CSV",
      "time": "20 min",
      "description": "Make the results usable. pandas turns a list of dicts into one clean spreadsheet, even when different documents are missing different fields.",
      "steps": [
        {
          "instruction": "Create `csv_writer.py` with this code:",
          "prompt": "\"\"\"\nStep 2 of the Basic Data Extractor Agent.\n\nThis file has one job: take the list of extracted-field dicts and turn\nthem into rows of a real CSV, using pandas. Nothing here talks to the\nAI - it's plain, fully-testable code you can run on its own.\n\"\"\"\n\nimport pandas as pd\n\nfrom extractor import FIELDS\n\n# Column order in the final CSV. source_file goes first so you can always\n# trace a row back to the document it came from - useful the moment you\n# spot a wrong-looking value and want to go check the original text.\nCOLUMNS = [\"source_file\"] + list(FIELDS.keys())\n\n\ndef write_csv(records, output_path=\"output.csv\"):\n    \"\"\"\n    Writes a list of extracted-field dicts to a CSV file.\n\n        write_csv([{\"source_file\": \"a.txt\", \"NAME\": \"Ada\", ...}])\n\n    Returns the output path, so main.py can print where the file went.\n    Raises ValueError if there is nothing to write.\n    \"\"\"\n    if not records:\n        raise ValueError(\"No records to write - nothing was extracted.\")\n\n    df = pd.DataFrame(records)\n\n    # Make sure every expected column exists and appears in a fixed\n    # order, even if every single record happened to be missing the same\n    # field (e.g. none of the sample documents mentioned an AMOUNT).\n    # Without this, pandas would just drop that column from the CSV\n    # entirely, and the column layout would silently change from run to\n    # run depending on which documents you happened to feed it.\n    for column in COLUMNS:\n        if column not in df.columns:\n            df[column] = None\n    df = df[COLUMNS]\n\n    # utf-8-sig (not plain utf-8) so accented characters and the naira\n    # sign (NGN's real symbol, U+20A6) don't turn into mojibake the\n    # moment someone opens this file in Excel instead of a text editor.\n    df.to_csv(output_path, index=False, encoding=\"utf-8-sig\")\n    return output_path\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check it works, with no AI involved:\n    #     python csv_writer.py\n    import os\n\n    sample_records = [\n        {\n            \"source_file\": \"business_card.txt\",\n            \"NAME\": \"Sarah Okafor\",\n            \"EMAIL\": \"sarah.okafor@fintechsolutions.ng\",\n            \"PHONE\": \"+234 803 555 0192\",\n            \"DATE\": None,\n            # AMOUNT deliberately omitted from this record entirely -\n            # not even set to None - to check the per-row case below.\n        },\n        {\n            # NAME, DATE and AMOUNT all omitted here too. Between these\n            # two records, AMOUNT never appears in a single dict - this\n            # is the \"every record is missing the same field\" case the\n            # COLUMNS loop above exists to handle.\n            \"source_file\": \"job_posting.txt\",\n            \"EMAIL\": \"careers@technova.io\",\n            \"PHONE\": None,\n        },\n    ]\n\n    path = write_csv(sample_records, output_path=\"test_output.csv\")\n    print(f\"Wrote {len(sample_records)} rows to {path}\")\n\n    check = pd.read_csv(path)\n    print(\"\\nColumns:\", list(check.columns))\n    assert list(check.columns) == COLUMNS, \"Column order should be fixed, not depend on which record has which keys\"\n    assert pd.isna(check.loc[0, \"AMOUNT\"]), \"A column no record provided should still exist, and be blank\"\n    assert pd.isna(check.loc[1, \"NAME\"]), \"A per-row missing field should read back as blank, not the string 'None'\"\n\n    print(\"\\nRow 2 (job_posting):\")\n    print(check.iloc[1])\n\n    os.remove(path)\n    print(f\"\\nCleaned up {path}. All csv_writer self-tests passed.\")\n",
          "verify": "Run `python csv_writer.py` - no AI call, no credits spent. It writes a small test CSV, checks the column order and the blank cells are correct, deletes the test file, and prints `All csv_writer self-tests passed.`"
        }
      ],
      "goFurther": "Add a `confidence` column that the AI also fills in (high/medium/low) for how sure it is about the whole extraction, and sort the final CSV so the rows most worth double-checking float to the top."
    },
    {
      "number": 3,
      "title": "Wire it together and batch-process the samples",
      "time": "20 min",
      "description": "One file at a time is a script; a whole folder in one run is a tool. This build ties extractor.py and csv_writer.py together and runs them across every sample document.",
      "steps": [
        {
          "instruction": "Create `main.py` with this code:",
          "prompt": "\"\"\"\nStep 3 of the Basic Data Extractor Agent - runs the whole pipeline.\n\nRun it with:      python main.py\n\"\"\"\n\nimport os\n\nfrom csv_writer import write_csv\nfrom extractor import extract_fields\nfrom sdt_ai import AIError\n\nSAMPLE_DIR = \"sample_data\"\nOUTPUT_PATH = \"output.csv\"\n\n\ndef process_folder(folder_path=SAMPLE_DIR):\n    \"\"\"\n    Reads every .txt file in folder_path, extracts fields from each with\n    the AI, and returns a list of record dicts ready for write_csv().\n\n    Each file is wrapped in its own try/except, so one bad file (a\n    network blip, a reply in a shape parse_fields() didn't expect)\n    can't stop the whole batch - you get results for every file that\n    worked, plus a clear message about the ones that didn't.\n    \"\"\"\n    if not os.path.isdir(folder_path):\n        raise ValueError(f\"Could not find a folder at '{folder_path}'.\")\n\n    filenames = sorted(f for f in os.listdir(folder_path) if f.endswith(\".txt\"))\n    if not filenames:\n        raise ValueError(f\"No .txt files found in '{folder_path}'.\")\n\n    records = []\n    for filename in filenames:\n        path = os.path.join(folder_path, filename)\n        with open(path, \"r\", encoding=\"utf-8\") as f:\n            text = f.read()\n\n        print(f\"Extracting from {filename}...\")\n        try:\n            record = extract_fields(text, source_file=filename)\n            records.append(record)\n        except AIError as problem:\n            # AIError messages are already written to be read - show\n            # them as-is and move on to the next file.\n            print(f\"  Skipped {filename}: {problem}\")\n\n    return records\n\n\nif __name__ == \"__main__\":\n    records = process_folder()\n\n    if not records:\n        print(\"\\nNothing was extracted - check the errors above.\")\n    else:\n        path = write_csv(records, output_path=OUTPUT_PATH)\n        print(f\"\\nSaved {len(records)} records to {path}\")\n",
          "verify": "Run `python main.py` - it prints `Extracting from ...` for each of the 5 files in sample_data/, then `Saved 5 records to output.csv`. Open output.csv - you should see one row per document, with blanks (not guesses) wherever a field genuinely isn't in that document."
        }
      ],
      "goFurther": "🛠️ Break it on purpose: temporarily move every file out of sample_data/ except product_review.txt (the coffee-maker review - none of your five fields are present in it), then run `python main.py` again. Open output.csv and confirm every column for that row is blank, not a plausible-looking guess like a fake name or price."
    },
    {
      "number": 4,
      "phaseLabel": "🎯 Challenge",
      "title": "Challenge: add your own field without breaking the \"none\" defense",
      "time": "20 min",
      "description": "The real test of whether you understand this tool isn't whether it runs - it's whether it still refuses to fabricate an answer after you've changed it yourself.",
      "steps": [
        {
          "instruction": "Add ONE new field to the FIELDS dict in extractor.py - pick something that appears in at least one sample file but not all of them (a job title, a company name, a listing location). Write your own one-line description for it, the same style as the existing five:",
          "prompt": "FIELDS = {\n    \"NAME\": \"The full name of a specific person mentioned in the text (not a company or product name).\",\n    \"EMAIL\": \"An email address mentioned in the text.\",\n    \"PHONE\": \"A phone number mentioned in the text, in whatever format it appears.\",\n    \"DATE\": \"A specific date mentioned in the text (a deadline, listing date, event date, etc.).\",\n    \"AMOUNT\": \"A specific monetary amount mentioned in the text (a price, salary, fee), including its currency symbol or code.\",\n    # Add your own field here. Example:\n    # \"COMPANY\": \"The name of a company or organisation mentioned in the text.\",\n    \"YOUR_FIELD_NAME\": \"TODO: write your own one-line description of what counts as a match.\",\n}",
          "verify": "Run `python main.py` again. Open output.csv: (1) every existing row still has its original values in the old columns - you didn't break anything; (2) your new column has a real value on the document(s) where it applies; (3) run it specifically against sample_data/product_review.txt - your new column for that row must come back blank, since a coffee-maker review has no job title, company name, or address to honestly report."
        },
        {
          "instruction": "In extractor.py's self-test block, add a fourth synthetic reply where your new field's marker is present but set to \"none\", to prove the missing-value defense covers the field you just added too:",
          "prompt": "    print(\"\\n--- Testing your new field's missing-value case ---\")\n    your_field_missing_reply = \"\"\"[NAME]\nnone\n\n[EMAIL]\nnone\n\n[PHONE]\nnone\n\n[DATE]\nnone\n\n[AMOUNT]\nnone\n\n[YOUR_FIELD_NAME]\nnone\n\n[END]\"\"\"\n    result = parse_fields(your_field_missing_reply)\n    # TODO: replace YOUR_FIELD_NAME on both sides below with your actual field name\n    assert result[\"YOUR_FIELD_NAME\"] is None\n    print(\"New field's missing-value case handled correctly.\")",
          "verify": "Run `python extractor.py` - your new assertion must pass alongside the original three self-tests, ending in `All parser self-tests passed.` again. An AssertionError here means your field name in FIELDS doesn't exactly match the marker name in your test reply (case and spelling both matter)."
        }
      ]
    }
  ],
  "portfolio": "You just built a data extraction pipeline that turns messy, real-world text into a clean spreadsheet - and proved it refuses to fabricate values it can't find. Take a screenshot of output.csv next to one of your sample documents, and add \"Basic Data Extractor Agent\" to your build portfolio.",
  "portfolioPrompt": "I just built a data extraction agent: it reads unstructured text (business cards, email signatures, listings, job postings), uses my own AI key (Gemini or Claude) to pull out name/email/phone/date/amount fields via a bracket-marker format designed to degrade gracefully instead of breaking like JSON does, and compiles everything into a clean CSV with pandas - with a parser I tested against missing fields and unexpected AI output.\n\nHelp me write:\n1. A 2-3 sentence project description for my portfolio site\n2. A short LinkedIn post announcing it\n3. Three resume-style bullet points describing what I built and the skills it shows"
}$sess$::jsonb,
  null, null,
  $tsh$[
  {
    "issue": "The AI writes a real-looking but wrong value for a field that isn't in the text at all (a fabricated phone number, a guessed date)",
    "fix": "This is exactly why the prompt tells the AI to write \"none\" for anything it can't find, and why parse_fields() turns that into a real None rather than trusting whatever text comes back. If you still see fabricated values, make the field's description in FIELDS more specific (e.g. \"a phone number that literally appears in the text\" rather than just \"a phone number\") and re-run - vague field descriptions invite the AI to fill in a plausible guess."
  },
  {
    "issue": "extractor.py runs but every field comes back None, even on business_card.txt which clearly has a name, email and phone",
    "fix": "Print the raw reply before parsing it (add print(reply) inside extract_fields) to see the AI's actual output. Usually the markers don't match FIELDS exactly - check for typos or extra characters inside the brackets. Lowercase markers like [name] are already handled (parse_fields() upper-cases before comparing), so if that's not it, compare the raw reply line-by-line against what build_prompt() actually asked for."
  },
  {
    "issue": "The CSV opens in Excel with broken accented characters or a garbled currency symbol",
    "fix": "write_csv() already saves with encoding=\"utf-8-sig\" instead of plain \"utf-8\" for exactly this reason - if you changed that line while editing, put it back. Plain utf-8 displays fine in a text editor, but Excel's default import assumes a different encoding and mangles anything outside plain ASCII."
  },
  {
    "issue": "main.py stops partway through the folder instead of finishing all 5 files",
    "fix": "Each file's extraction is already wrapped in its own try/except AIError inside process_folder() - if you get a full crash instead of a \"Skipped ...\" line and the loop continuing, check whether you accidentally moved the extract_fields() call outside that try block while editing."
  },
  {
    "issue": "python extractor.py or python csv_writer.py prints a UnicodeEncodeError instead of your test output",
    "fix": "This happens on Windows when a value contains a character your terminal's default codepage can't display (commonly a currency symbol). It's a console display issue, not a bug in your data - the CSV file itself is saved correctly with encoding=\"utf-8-sig\" regardless of what your terminal can show. Run the command from a UTF-8 terminal (Windows Terminal, or `chcp 65001` first) if you want the symbol itself to print."
  }
